/**
 * WU30 — THE OG CARD CONTRACT (one source of truth).
 * ============================================================================
 * The share card `public/assets/brand/og-default.png` (1200x628) is generated by
 * `scripts/generate-dither.mjs` from THIS file, and `scripts/check-iteration-2.mjs`
 * verifies the committed PNG against the same numbers. Keeping the geometry and
 * the colour model here means the generator and the checker cannot drift while
 * still being independent where it matters: the checker re-rasterises the
 * committed outline SVGs itself and reads the committed PNG's own pixels.
 *
 * The ground is the SAME composition the public page renders — the page's exact
 * `convert` call, roll, palette (`joyan-page`) and overlays — rasterised through
 * the same engine (`scripts/scene-src/`), in Node, with no browser anywhere.
 * The page's delivery cell is 8 px over a 160x80 grid (1280x640); the card is
 * that same raster cropped by WHOLE CELLS (5 columns and 1 row off each side)
 * and padded with two 1-cell-wide ground bands top and bottom, so every dot on
 * the card is an unclipped cell of the page's scene.
 *
 * Everything the card paints is a blend between the ground and ONE `joyan-page`
 * entry (the dot field, the scrim, the calm panel, the text antialiasing), and
 * the blend is snapped to a fixed coverage ladder so the whole card fits a
 * lossless palette PNG. `cardPalette()` enumerates every colour the card may
 * contain.
 */

/** The page palette id and grid the card reuses. */
export const PAGE_PALETTE = 'joyan-page';
export const SCENE = Object.freeze({
  cols: 160,
  rows: 80,
  roll: 18,
  overlays: Object.freeze(['stars', 'aurora', 'wash', 'vignette']),
  id: 'joyan-coming-hero',
  /** The page converts the gitignored fixture when it is present, else our mark. */
  fixture: 'dist-motion-verify/wu18/input/blade-runner-unicorn-line-transparent.svg',
  fallbackInputId: 'joyan-mark',
});

export const CARD = Object.freeze({
  width: 1200,
  height: 628,
  cell: 8,
  /** Whole-cell window into the page's 1280x640 raster (5 columns, 1 row each side). */
  crop: Object.freeze({ left: 40, top: 8, width: 1200, height: 624 }),
  /** Ground bands that bring 624 up to the 628 production height. */
  band: 2,
});

/** Coverage ladder: every painted colour is ground + (ink - ground) * k / STEPS. */
export const COVERAGE_STEPS = 20;

/**
 * The page's own hero scrim (`JoyanComingHero.astro` — `.scrim`), same angle and
 * same stops. Its colour is rgb(11 11 12), i.e. exactly the ground, which is why
 * compositing it is the same as scaling each dot's coverage: it can never invent
 * a colour off the ground->ink line.
 */
export const SCRIM = Object.freeze({
  angleDeg: 105,
  stops: Object.freeze([[0, 0.92], [0.34, 0.85], [0.62, 0.4], [1, 0.55]]),
});

/**
 * The calm panel: a soft ground-coloured falloff around the text block, so the
 * text sits on exactly the ground (its antialiasing stays an exact single-dot
 * blend) and the left side of the card is quiet. Panel bounds are derived from
 * the text boxes below, never hand-tuned.
 */
export const PANEL = Object.freeze({ padding: 26, ramp: 96 });

/** The card's inks: all `joyan-page` entries (never a new colour). */
export const INKS = Object.freeze({
  wordmark: '#f4f2ed', // joyan-page 10 — bone-50, the site's primary text token
  tagline: '#d9d7d2', //  joyan-page 9  — the supporting line, one step quieter
  prompt: '#ffb000', //   joyan-page 7  — the reserved amber, ONLY as the attention mark
});

/** The committed outline SVGs (derived once by scripts/motion-src/derive-outlines.py). */
export const OUTLINES = Object.freeze({
  wordmark: 'public/assets/brand/joyan-wordmark-michroma-outlines.svg',
  tagline: 'public/assets/brand/og-tagline-mono-outlines.svg',
  prompt: 'public/assets/brand/og-prompt-mono-outlines.svg',
});

/**
 * The three text layers, in paint order. `width` is the target width in card
 * pixels; the height follows the SVG's own aspect via `outlineBox`.
 */
export const LAYERS = Object.freeze([
  Object.freeze({ id: 'prompt', role: 'prompt', ink: 'prompt', svg: OUTLINES.prompt, x: 88, y: 404, width: 22 }),
  Object.freeze({ id: 'tagline', role: 'tagline', ink: 'tagline', svg: OUTLINES.tagline, x: 128, y: 399, width: 560 }),
  Object.freeze({ id: 'wordmark', role: 'wordmark', ink: 'wordmark', svg: OUTLINES.wordmark, x: 84, y: 232, width: 500 }),
]);

export const GROUND_HEX = '#0b0b0c';

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const smoothstep = (t) => { const c = clamp01(t); return c * c * (3 - 2 * c); };

export const hexToRgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
export const rgbToHex = (rgb) => `#${rgb.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('')}`;

/** The `joyan-page` entries other than the ground. */
export function cardInks(palette) {
  return palette.slice(1);
}

/**
 * Every colour the card may contain: the ground, plus each non-ground
 * `joyan-page` entry at every rung of the coverage ladder.
 */
export function cardPalette(palette) {
  const ground = hexToRgb(palette[0]);
  const colours = new Map([[rgbToHex(ground), ground]]);
  for (const hex of cardInks(palette)) {
    const ink = hexToRgb(hex);
    for (let k = 1; k <= COVERAGE_STEPS; k++) {
      const rgb = ground.map((g, c) => Math.round(g + (ink[c] - g) * (k / COVERAGE_STEPS)));
      colours.set(rgbToHex(rgb), rgb);
    }
  }
  return colours;
}

/**
 * Snap one colour to the card palette (nearest by squared RGB distance, first
 * index wins ties). The result is ALWAYS a palette entry, so a composed card can
 * never contain a colour the checker does not know about.
 */
export function makeSnapper(palette) {
  const colours = cardPalette(palette);
  const list = [...colours.values()];
  const cache = new Map();
  return (r, g, b) => {
    const key = (r << 16) | (g << 8) | b;
    const hit = cache.get(key);
    if (hit) return hit;
    let best = list[0];
    let bestScore = Infinity;
    for (const entry of list) {
      const dr = r - entry[0], dg = g - entry[1], db = b - entry[2];
      const score = dr * dr + dg * dg + db * db;
      if (score < bestScore) { bestScore = score; best = entry; }
    }
    cache.set(key, best);
    return best;
  };
}

/** The page's scrim alpha at a card pixel (CSS `linear-gradient(105deg, ...)`). */
export function scrimAlpha(x, y) {
  const rad = (SCRIM.angleDeg * Math.PI) / 180;
  const dx = Math.sin(rad);
  const dy = -Math.cos(rad);
  const length = Math.abs(CARD.width * dx) + Math.abs(CARD.height * dy);
  const t = ((x - CARD.width / 2) * dx + (y - CARD.height / 2) * dy) / length + 0.5;
  const u = clamp01(t);
  const stops = SCRIM.stops;
  if (u <= stops[0][0]) return stops[0][1];
  for (let i = 0; i + 1 < stops.length; i++) {
    const [t0, a0] = stops[i];
    const [t1, a1] = stops[i + 1];
    if (u <= t1) return a0 + (a1 - a0) * ((u - t0) / (t1 - t0));
  }
  return stops[stops.length - 1][1];
}

/** The calm panel: 0 inside the text block, 1 outside its padded, ramped edge. */
export function panelFactor(x, y, rect) {
  const dx = Math.max(rect.x0 - x, x - rect.x1, 0);
  const dy = Math.max(rect.y0 - y, y - rect.y1, 0);
  return smoothstep(Math.hypot(dx, dy) / PANEL.ramp);
}

/** The union of the text boxes (integer, as painted) padded by PANEL.padding. */
export function panelRect(boxes) {
  const x0 = Math.min(...boxes.map((box) => box.x));
  const y0 = Math.min(...boxes.map((box) => box.y));
  const x1 = Math.max(...boxes.map((box) => box.x + box.width));
  const y1 = Math.max(...boxes.map((box) => box.y + box.height));
  return {
    x0: x0 - PANEL.padding, y0: y0 - PANEL.padding,
    x1: x1 + PANEL.padding, y1: y1 + PANEL.padding,
  };
}

/** Parse the `<svg>` root's intrinsic width/height (the derived outlines carry both). */
export function svgSize(svgText) {
  const width = Number(svgText.match(/\bwidth="([\d.]+)"/)?.[1]);
  const height = Number(svgText.match(/\bheight="([\d.]+)"/)?.[1]);
  if (!(width > 0) || !(height > 0)) throw new Error('outline SVG must carry intrinsic width/height');
  return { width, height };
}

/**
 * One layer's exact card box, in whole pixels: the target width and the SVG's
 * own aspect. Both the generator (to paint) and the checker (to mask) call this,
 * so the mask can never be one pixel off the ink.
 */
export function layerBox(svgText, layer) {
  const size = svgSize(svgText);
  const width = Math.max(1, Math.round(layer.width));
  const height = Math.max(1, Math.round((layer.width * size.height) / size.width));
  return { x: Math.round(layer.x), y: Math.round(layer.y), width, height };
}
